  if (node is! YamlMap) {
    throw ConfigException('trajectory must be a map, got: $node');
  }
  var section = const TrajectorySection();
  for (final key in node.keys) {
    final value = node[key];
    switch (key) {
      case 'wireDump':
        if (value is! bool) {
          throw ConfigException('"trajectory.wireDump" must be a boolean');
