          now.difference(DateTime.fromMillisecondsSinceEpoch(file.mtimeMs)) >
          ttl;
      if (!expired && total <= maxBytes) break;
      await _env.remove(file.path, force: true);
      total -= file.size;
      deleted++;
    }
    return deleted;
  }

