/// boot; the defaults are never written so the file stays minimal.
final class TrajectorySection {
  const TrajectorySection({
    this.wireDump = false,
    this.requestBlobs = true,
    this.requestBlobMaxMb = 50,
    this.requestBlobTtlDays = 30,
