          maxBytes: config.trajectoryRequestBlobMaxMb << 20,
          ttlDays: config.trajectoryRequestBlobTtlDays,
        )).write(
          detail: event.detail,
          rawWireDump: event.rawWireDump,
          redactWireDump: config.redactionPipeline?.redact,
