        expect(spill, isNotNull);
        expect(spill!.file, '.fah/trajectories/s1/requests/1.json');
        expect(spill.wireDumpHash, isNull);
        final read = await env.readTextFile(spill.file);
        final decoded = jsonDecode(read.valueOrNull!) as Map;
