```dart
/// Sweps expired blobs (age past [ttlDays]) in EVERY session's request
/// dir under `.fah/trajectories/` — the boot-time reaper ...
Future<int> sweepExpiredEverywhere() async {
 final root = '.fah/trajectories';
 final listing = await _env.listDir(root);
 final dirs = listing.valueOrNull ?? const <FileInfo>[];
 var deleted = 0;
 for (final entry in dirs) {
   if (!entry.isDirectory) continue; // check FileInfo shape
   deleted += await enforceBudget(dir: '${root}/${entry.name}/requests');
 }
 return deleted;
