/// session keeps nothing).
Future<int> sweepExpiredEverywhere() async {
 var deleted = 0;
 final listing = await _env.listDir('.fah/trajectories');
 for (final entry in listing.valueOrNull ?? const <FileInfo>[]) {
   if (!entry.isDirectory) continue;
   deleted += await _sweepExpiredIn('.fah/trajectories/${entry.name}/requests');
 }
 return deleted;
}

Future<int> _sweepExpiredIn(String dir) async {
 final listing = await _env.listDir(dir);
 final files = listing.valueOrNull ?? const <FileInfo>[];
 if (files.isEmpty) return 0;
 final now = _clock();
 final ttl = Duration(days: ttlDays);
 var deleted = 0;
 for (final file in files) {
   final expired = now.difference(DateTime.fromMillisecondsSinceEpoch(file.mtimeMs)) > ttl;
   if (!expired) continue;
   await _env.remove(file.path, force: true);
   deleted++;
 }
 return deleted;
}
