  test('rejects a non-boolean wireDump', () {
    final file = File('${tmp.path}/.fah/config.yaml');
    file.createSync(recursive: true);
    file.writeAsStringSync('trajectory:\n  wireDump: "yes"\n');
    expect(
      () => loadCliConfig(tmp.path),
