  final yaml = CliConfig(
    jobs: const JobsConfig(staleHours: 48, logRetentionDays: 7),
  ).toYaml();
  expect(yaml, contains('jobs:\n  staleHours: 48'));
  expect(yaml, contains('logRetentionDays: 7'));
});

