```dart
 /// Deletes every blob past [ttlDays] in EVERY session's request dir
 /// under `.fah/trajectories/` — the disk-footprint tail survives the
 /// per-session rotation otherwise (ended sessions never write again).
 /// Returns the deleted count; best-effort (listing failures skip that
 /// dir, removal failures are swallowed).
 Future<int> sweepExpiredEverywhere() async {
  var deleted = 0;
  final root = await _env.listDir('.fah/trajectories');
  for (final entry in root.valueOrNull ?? const <FileInfo>[]) {
    if (entry.kind != FileKind.directory) continue;
    deleted += await _sweepExpiredIn(
      '${'.fah/trajectories'}/${entry.name}/requests',
    );
  }
  return deleted;
 }

 Future<int> _sweepExpiredIn(String dir) async {
  final listing = await _env.listDir(dir);
  final files = listing.valueOrNull;
  if (files == null || files.isEmpty) return 0;
  final now = _clock();
  final ttl = Duration(days: ttlDays);
  var deleted = 0;
  for (final file in files) {
    final expired =
        now.difference(DateTime.fromMillisecondsSinceEpoch(file.mtimeMs)) >
        ttl;
    if (!expired) continue;
    final removed = await _env.remove(file.path, force: true);
    if (removed.isOk) deleted++;
  }
  return deleted;
 }
``

